    if match_ref_val == 0:
        if reference == "BR1 Sales":
            rows_to_keep.append(row)
            sum_br1_sales += amount
        else:
            continue  # Skip rows with Match Ref and Val = 0 except for 'BR1 Sales'
    else:
        rows_to_keep.append(row)

# Step 3: Write the computed values back to the worksheet
