    if isinstance(cell.value, datetime):
        date_columns.append(cell.column)

# Read the data into a dictionary: {item: {date: quantity, ...}, ...}
item_data = {}
for row in data_sheet.iter_rows(min_row=first_data_row, max_col=data_sheet.max_column, values_only=True):
