    quantities = {}
    for col_idx, qty in enumerate(row):
        if col_idx in date_columns:
            date = data_sheet.cell(row=header_row, column=col_idx + 1).value
            quantities[date] = qty
    item_data[item] = quantities

# Write the transposed data to the 'Transpose' sheet
transpose_sheet.delete_rows(3, transpose_sheet.max_row - 2)
for idx, (item, dates) in enumerate(item_data.items(), start=3):
