        continue
    try:
        date = datetime.strptime(date_str, "%Y-%m")
    except ValueError:
        continue
    data = []
    for cell in row:
        value = cell.value
        if value in (-9999, "M"):
            continue
        if value is None:
            data.append("NA")
        else:
            data.append(value)
    group_a_data.append((date, data))

# Prepare Group B data
group_b_data = []
for date, data in group_a_data:
    for i, value in enumerate(data):
        if value == "NA":
            group_b_data.append((date, "NA"))
        else:
            group_b_data.append((date, value))

# Write Group B data to the answer range
for i, (date, value) in enumerate(group_b_data, start=20):
    ws.cell(row=i, column=2, value=value)

