from openpyxl import load_workbook

# Load the workbook and select the sheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Read the data into a list of dictionaries
data = []
for row in ws.iter_rows(min_row=2, max_col=3, values_only=True):
    department, status, turnaround_time = row
    if department and status and turnaround_time:
        data.append({
            'department': department,
            'status': status,
            'turnaround_time': turnaround_time
        })

# Calculate the average turnaround time for each department
department_averages = {}
for entry in data:
    if entry['status'] in ['In Progress', 'In Review'] and entry['turnaround_time'] >= 6:
        dept = entry['department']
        if dept not in department_averages:
            department_averages[dept] = {'total': 0, 'count': 0}
        department_averages[dept]['total'] += entry['turnaround_time']
        department_averages[dept]['count'] += 1

# Write the results to the answer range
for i, row in enumerate(ws.iter_rows(min_row=11, max_row=13, min_col=2, max_col=2)):
    cell = row[0]
    department = ws.cell(row=cell.row, column=1).value
    if department in department_averages:
        avg = department_averages[department]['total'] / department_averages[department]['count']
        cell.value = avg
    else:
        cell.value = None

# Save the workbook
wb.save('output.xlsx')
